QS = [
 (S, "Which Companion (Sahabi) of the Holy Prophet (PBUH) served him for ten years in Madinah?", ["Hazrat Anas bin Malik (RA)", "Hazrat Bilal bin Rabah (RA)", "Hazrat Abdullah bin Masud (RA)", "Hazrat Abu Hurairah (RA)"], 0,
  "Hazrat Anas bin Malik (RA) was given to the Prophet (PBUH) as a boy by his mother and served him for about ten years in Madinah.", "Some sources name Hazrat Zaid bin Haritha (RA) as the Prophet's close helper, but the ten year service is mostly credited to Anas bin Malik (RA).", [597, 4020, 4291, 4292, 623]),
 (S, "In which session of the All India Muslim League was the Lahore (Pakistan) Resolution passed in March 1940?", ["25th session", "26th session", "28th session", "27th session"], 3,
  "The Lahore Resolution was passed at the 27th annual session of the All India Muslim League held at Minto Park, Lahore.", "The resolution was moved by A. K. Fazlul Haq and presided over by Quaid-e-Azam.", [414]),
 (S, "What comes next in the series: Z4, X8, V12, ?", ["T16", "S16", "U16", "T14"], 0,
  "The letters move back by two (Z, X, V, T) and the numbers go up by 4 (4, 8, 12, 16). So the next term is T16.", "Skipping one letter each time gives the alphabet position falling by 2 each step.", [2524]),
 (S, "What comes next in the series: Aa, Bb, Cc, Dd, ?", ["Ff", "Ee", "Ed", "EE"], 1,
  "Each term has a capital letter and its small letter, moving one letter forward each time. After Dd comes Ee.", "The English alphabet has 26 letters.", [3670]),
 (S, "What comes next in the series: A2, D9, H16, M23, ?", ["R30", "S30", "S29", "T30"], 1,
  "The letters jump by 3, 4, 5 places (A, D, H, M) so the next jump is 6, giving S. The numbers increase by 7 each time (2, 9, 16, 23), giving 30. So the next term is S30.", "M is the 13th letter, and 13 + 6 = 19, which is S.", [3844]),
 (S, "By which symbol is the universal set usually represented in set theory?", ["U", "N", "phi", "Z"], 0,
  "The universal set, which contains all elements under consideration, is written with the capital letter U.", "The empty set is written with the symbol phi or with empty braces.", [1470]),
 (S, "If A and B are two sets, what is the set A union B?", ["The set of elements common to both A and B", "The set of all elements in A or in B or in both", "The set of elements in A but not in B", "The set with no elements"], 1,
  "The union of A and B (written A U B) contains every element that belongs to A, to B, or to both.", "The set of common elements is called the intersection.", [1867, 1856]),
 (S, "What is a singleton set?", ["A set with no element", "A set with exactly one element", "A set with two elements", "A set with infinite elements"], 1,
  "A singleton set has exactly one element, for example {5}.", "A set with no element is called the empty or null set.", [2653]),
 (S, "Shahzia Sikander, who is well known internationally, is a Pakistani-born what?", ["Visual artist", "Cricketer", "Politician", "Singer"], 0,
  "Shahzia Sikander, born in Lahore in 1969, is a contemporary visual artist famous for reinventing Indo-Persian miniature painting.", "She studied at the National College of Arts, Lahore, and later moved to the United States.", [1211]),
 (S, "Between which two countries was the Shimla Agreement of 1972 signed?", ["Pakistan and Bangladesh", "Pakistan and China", "India and Bangladesh", "Pakistan and India"], 3,
  "The Shimla Agreement was signed by Pakistan and India in July 1972 after the 1971 war.", "Under it both countries agreed to settle disputes peacefully and respect the Line of Control in Kashmir.", [1457, 670, 1129]),
 (S, "Which prophet is famous for building the ship (ark) that saved the believers from the great flood?", ["Hazrat Ibrahim (AS)", "Hazrat Nuh (AS)", "Hazrat Musa (AS)", "Hazrat Yunus (AS)"], 1,
  "Allah ordered Hazrat Nuh (Noah) AS to build a ship, and he saved the believers and pairs of animals in it from the flood.", "According to the Quran, the ark came to rest on Mount Judi.", [2390, 4455]),
 (S, "What does the idiom \"cold shoulder\" mean?", ["To treat someone in an unfriendly way and ignore them", "To feel a pain in the shoulder", "To welcome someone warmly", "To carry a heavy load"], 0,
  "To give someone the cold shoulder means to deliberately ignore them or treat them coldly.", "An idiom has a meaning different from the literal meaning of its words.", [3019]),
 (S, "In which Islamic month was the Holy Quran first revealed to Prophet Muhammad (PBUH)?", ["Muharram", "Shaban", "Rajab", "Ramadan"], 3,
  "The Quran began to be revealed in the month of Ramadan, on Laylat-ul-Qadr, in the Cave of Hira.", "Muslims fast in Ramadan, which is the ninth month of the Islamic calendar.", [2068]),
]
